import java.util.*;class Solution{List<List<String>>o=new ArrayList<>();boolean p(String s,int l,int r){while(l<r)if(s.charAt(l++)!=s.charAt(r--))return false;return true;}void f(String s,int st,List<String>v){if(st==s.length()){o.add(new ArrayList<>(v));return;}for(int e=st;e<s.length();e++)if(p(s,st,e)){v.add(s.substring(st,e+1));f(s,e+1,v);v.remove(v.size()-1);}}public List<List<String>> partition(String s){f(s,0,new ArrayList<>());return o;}}
